const j = $json;

const intentoActual =
  Number(j.intento ?? 1) + 1;

return {
  json: {
    ...j,
    intento: intentoActual,
    max: 4
  }
};

// ===== CONFIGURACION =====
// Este workflow atiende SOLO eventos de Windows.
const SO_FLUJO = 'windows';
// Pasar a true SOLO cuando el reinicio de IIS este validado.
const WINDOWS_HABILITADO = true;
// Zona horaria del servidor Zabbix (Costa Rica: UTC-6, sin horario de verano).
const TZ_ZABBIX = '-06:00';

const catalogo = {
  crm_linux:   { ambiente: 'A', so: 'linux',   host: '192.168.20.11', url: 'http://192.168.20.11:8080', tipos: ['http_down', 'container_down'], remediar: true },
  crm_windows: { ambiente: 'B', so: 'windows', host: '192.168.20.12', url: 'http://192.168.20.12/espocrm',      tipos: ['http_down', 'service_down'],   remediar: WINDOWS_HABILITADO },
  // Bases de datos: el flujo NO las reinicia (solo avisa). Estan en el catalogo para que el aviso sea claro.
  db_linux:    { ambiente: null, so: 'linux',   host: '192.168.30.11', url: null, tipos: ['db_down'], remediar: false, motivoFijo: 'MariaDB Ubuntu (VM-03): solo alerta, sin reinicio automatico (por diseno)' },
  db_windows:  { ambiente: null, so: 'windows', host: '192.168.30.12', url: null, tipos: ['db_down'], remediar: false, motivoFijo: 'MariaDB Windows (VM-04): solo alerta, sin reinicio automatico (por diseno)' }
};

// ---------- 1. Datos recibidos ----------
const raw = $json.body !== undefined ? $json.body : $json;

// Busca un campo (target, incident_type, ...) en cualquier nivel del JSON recibido.
function buscar(o, clave, nivel = 0) {
  if (o === null || typeof o !== 'object' || nivel > 6) return null;
  if (o[clave] !== undefined && o[clave] !== null && o[clave] !== '') return o[clave];
  for (const k of Object.keys(o)) {
    const r = buscar(o[k], clave, nivel + 1);
    if (r !== null) return r;
  }
  return null;
}
// Todo el contenido recibido como texto (mensaje, asunto, nombre del trigger, host...).
let texto = '';
try { texto = typeof raw === 'string' ? raw : JSON.stringify(raw); } catch (e) { texto = String(raw); }
// Zabbix puede mandar el cuerpo como un JSON dentro de un texto: se des-escapa para poder leerlo.
const plano = texto.replace(/\\n/g, '\n').replace(/\\"/g, '"');
const bajo = plano.toLowerCase();

// ---------- 2. Objetivo y tipo de incidente ----------
let target = buscar(raw, 'target');
let tipo = buscar(raw, 'incident_type');
let origen = 'campos';

if (!target || !tipo) {
  origen = 'texto';
  target = null; tipo = null;
  if (/mariadb|mysql/.test(bajo)) {
    target = /windows/.test(bajo) ? 'db_windows' : 'db_linux';
    tipo = 'db_down';
  } else if (/\biis\b|w3svc/.test(bajo)) {
    target = 'crm_windows'; tipo = 'service_down';
  } else if (/windows/.test(bajo)) {
    target = 'crm_windows'; tipo = 'http_down';
  } else if (/ubuntu|linux|docker|contenedor|container|espocrm/.test(bajo)) {
    target = 'crm_linux';
    tipo = /contenedor|container|docker/.test(bajo) ? 'container_down' : 'http_down';
  }
}

// ---------- 3. Evento de recuperacion: no se actua ----------
const estado = String(buscar(raw, 'event_value') ?? buscar(raw, 'status') ?? '').toLowerCase();
const esRecuperacion = ['0', 'ok', 'resolved', 'resuelto'].includes(estado)
  || /has been resolved|\bresolved\b|\bresuelto\b|\brecuperad[oa]\b|\brecovery\b/.test(bajo);

// ---------- 4. Autorizacion ----------
const t = target ? catalogo[target] : null;
let autorizado = false;
let motivo = '';
if (esRecuperacion) motivo = 'Evento de recuperacion de Zabbix: no requiere accion';
else if (!t) motivo = 'No se reconocio el objetivo en el mensaje de Zabbix (target: ' + target + ')';
else if (!tipo) motivo = 'El evento no trae incident_type';
else if (t.so !== SO_FLUJO) motivo = 'Evento de ' + (t.so === 'windows' ? 'Windows' : 'Linux') + ' recibido en el flujo de ' + (SO_FLUJO === 'windows' ? 'Windows' : 'Linux') + ': no se actua aqui (revisar la accion de Zabbix)';
else if (!t.tipos.includes(tipo)) motivo = 'Tipo de incidente no permitido para ' + target + ': ' + tipo;
else if (!t.remediar) motivo = t.motivoFijo || ('Remediacion automatica de ' + target + ' deshabilitada: pendiente de validacion');
else autorizado = true;

// ---------- 5. Hora del evento ----------
// Si viene como campo ("2026.10.26 14:05:30") se usa; si no, se busca en el texto
// ("Problem started at 14:05:30 on 2026.10.26"). Sin hora valida, el flujo usa la llegada del webhook.
let event_time = buscar(raw, 'event_time');
if (!event_time) {
  const h = plano.match(/(\d{2}:\d{2}:\d{2})/);
  const f = plano.match(/(\d{4}[./-]\d{2}[./-]\d{2})/);
  if (h && f) event_time = f[1].replace(/[/-]/g, '.') + ' ' + h[1];
}
let t_evento_ms = null;
if (event_time) {
  const iso = String(event_time).trim().replace(/\./g, '-').replace(' ', 'T') + TZ_ZABBIX;
  const ms = Date.parse(iso);
  if (!isNaN(ms)) t_evento_ms = ms;
}

let event_id = buscar(raw, 'event_id');
if (!event_id) { const m = plano.match(/(?:problem id|event id|id del evento)[^0-9]{0,20}(\d+)/i); if (m) event_id = m[1]; }

const ahora = Date.now();
return { json: {
  target: target || null,
  incident_type: tipo,
  event_id: event_id || null,
  event_time: event_time || null,
  autorizado,
  es_recuperacion: esRecuperacion,
  motivo,
  clasificado_por: origen,
  recibido: plano.replace(/\s+/g, ' ').slice(0, 220),
  ambiente: t ? t.ambiente : null,
  so: t ? t.so : null,
  url: t ? t.url : null,
  host: t ? t.host : null,
  t_evento_ms,
  t_inicio_ms: ahora,
  t_inicio_n8n: new Date(ahora).toISOString()
} };

// ==================================================
// CONTROL DE INCIDENTES / PROTECCIÓN ANTI-BUCLE
// CRM WINDOWS - T-47
// ==================================================
//
// Máximo 2 incidentes automáticos del mismo objetivo
// dentro de 15 minutos.
//
// Cada incidente permitido puede realizar hasta
// 4 intentos de recuperación.
// ==================================================

const MAX_INCIDENTES = 2;
const VENTANA_MIN = 15;

const ventanaMs = VENTANA_MIN * 60 * 1000;
const estado = $getWorkflowStaticData('global');

estado.reinicios = estado.reinicios || {};

const ahora = Date.now();
const d = $json;

// Limpiar incidentes fuera de la ventana
const previos = (estado.reinicios[d.target] || [])
  .filter(ts => ahora - ts < ventanaMs);

// Validar si se permite un nuevo incidente automático
const permitido = previos.length < MAX_INCIDENTES;

if (permitido) {
  previos.push(ahora);
}

estado.reinicios[d.target] = previos;

// Calcular cuánto falta para volver a permitir otro incidente
const minutosEspera =
  permitido
    ? 0
    : Math.ceil(
        (ventanaMs - (ahora - previos[0])) / 60000
      );

return {
  json: {
    ...d,

    permitido,

    incidentes_en_ventana: previos.length,
    max_incidentes_ventana: MAX_INCIDENTES,
    ventana_min: VENTANA_MIN,
    minutos_espera: minutosEspera,

    // Cada incidente comienza en el intento 1
    intento: 1,

    // Máximo de intentos de recuperación
    max: 4
  }
};

// ==================================================
// MARCAR HORA DEL REINICIO
// CRM WINDOWS - T-47
// ==================================================
//
// Primer intento: datos desde "Control de reinicios".
// Intentos 2, 3 y 4: datos desde "Control de reintentos".
// ==================================================

let datos;

try {
  const retry = $('Control de reintentos').last().json;

  if (
    retry &&
    retry.intento !== undefined &&
    Number(retry.intento) > 1
  ) {
    datos = retry;
  }
} catch (e) {
  // Normal durante el primer intento.
}

if (!datos) {
  datos = $('Control de reinicios1').first().json;
}

const ssh = $json;
let error = '';

if (ssh.error) {
  error = String(
    ssh.error.message ||
    ssh.error
  );
} else if (
  ssh.code !== 0 &&
  ssh.code !== undefined
) {
  error = String(
    ssh.stderr ||
    ssh.stdout ||
    'codigo ' + ssh.code
  );
}

return {
  json: {
    ...datos,

    t_reinicio_ms: Date.now(),

    reinicio_ok:
      error === '',

    reinicio_error:
      error.slice(0, 300)
  }
};

// ==================================================
// MARCAR HTTP OK
// CRM WINDOWS - T-47
// ==================================================

const r = $('Marcar hora del reinicio1').last().json;

return {
  json: {
    ...r,

    t_http_ms: Date.now(),

    http_status:
      $json.statusCode ?? 'sin respuesta'
  }
};

// ===== CONFIGURACION DE UMBRALES =====
const UMBRALES = {
  login:            { normal: 3, advertencia: 5, critico: 8 },
  consulta:         { normal: 4, advertencia: 6, critico: 8 },
  registro:         { normal: 5, advertencia: 8, critico: 12 },
  buscar_contacto:  { normal: 6, advertencia: 9, critico: 14 }
};

// 1. Recuperamos los datos del flujo (Asegúrate de que este sea el nombre de tu nodo anterior)
const r = $('Marcar hora de HTTP OK1').last().json;
const ssh = $json; 

let rpa = { resultado: 'ERROR', segundos: null, pasos: [] };
try {
  const lineas = String(ssh.stdout || '').trim().split('\n');
  rpa = JSON.parse(lineas[lineas.length - 1]);
} catch (e) {
  rpa.mensaje = ssh.error ? 'Error SSH: ' + String(ssh.error.message || ssh.error) : 'Salida del RPA no interpretable';
}

// 2. Clasificamos los tiempos de cada paso
let alertasDegradacion = [];
let hayCritico = false;
let hayError = false;

const pasosClasificados = (rpa.pasos || []).map(p => {
  const pasoNombre = p.paso.toLowerCase();
  let clasificacion = 'NORMAL';
  let color = '🟢';

  if (p.resultado && p.resultado !== 'PASS') {
    // El paso FALLO (no es solo lentitud)
    clasificacion = 'ERROR';
    color = '🔴';
    hayError = true;
    hayCritico = true;
    alertasDegradacion.push(`🔴 ERROR: ${p.paso} fallo tras ${p.segundos}s`);
  } else if (UMBRALES[pasoNombre]) {
    if (p.segundos >= UMBRALES[pasoNombre].critico) {
      clasificacion = 'CRITICO';
      color = '🔴';
      hayCritico = true;
      alertasDegradacion.push(`🔴 CRÍTICO: ${p.paso} tardó ${p.segundos}s (límite: ${UMBRALES[pasoNombre].critico}s)`);
    } else if (p.segundos >= UMBRALES[pasoNombre].advertencia) {
      clasificacion = 'ADVERTENCIA';
      color = '🟠';
      alertasDegradacion.push(`🟠 ADVERTENCIA: ${p.paso} tardó ${p.segundos}s (límite: ${UMBRALES[pasoNombre].advertencia}s)`);
    }
  }

  return { ...p, clasificacion, color };
});

// 3. Calculamos los tiempos de acción y recuperación
const ahora = Date.now();
const ref = r.t_evento_ms != null ? r.t_evento_ms : r.t_inicio_ms;
const seg = (a, b) => (a == null || b == null) ? null : Math.round((b - a) / 100) / 10;
const f = v => v == null ? 'n/d' : v + ' s';
const hora = ms => ms == null ? 'n/d' : new Date(ms - 6 * 3600 * 1000).toISOString().replace('T', ' ').slice(0, 19) + ' (CR)';

const tAccion = seg(ref, r.t_reinicio_ms);
const tRecuperacion = r.t_http_ms != null ? seg(r.t_reinicio_ms, r.t_http_ms) : null;
const tTotal = seg(ref, ahora);

// 4. Armamos el mensaje final para Telegram
const pasosTexto = pasosClasificados.map(p => 
  `  ${p.color} ${p.paso}: ${p.segundos}s [${p.clasificacion}]`
).join('\n');

const encabezado = hayError ? '❌ ERROR DETECTADO POR EL RPA' : hayCritico ? '⚠️ DEGRADACIÓN CRÍTICA DETECTADA' : (rpa.resultado === 'PASS' ? '✅ RECUPERADO' : '⚠️ RECUPERADO, PERO EL RPA FALLO');

const mensaje = [
  `${encabezado}: ${r.target} (${r.incident_type})`,
  `Hora del evento: ${r.event_time ? r.event_time + ' (Zabbix)' : hora(r.t_inicio_ms)}`,
  `Hora de recuperacion: ${hora(ahora)}`,
  `Reinicio: ${r.reinicio_ok ? 'correcto' : 'con error'} | HTTP: ${r.http_status}`,
  `T-accion: ${f(tAccion)} | T-recuperacion: ${f(tRecuperacion)} | T-total: ${f(tTotal)}`,
  `--- Tiempos del RPA ---`,
  pasosTexto,
  alertasDegradacion.length > 0 ? `\n⚠️ ALERTAS DE RENDIMIENTO:\n${alertasDegradacion.join('\n')}` : null,
  r.intento ? `Intento de recuperación: ${r.intento} de ${r.max || 4}` : null
].filter(Boolean).join('\n');

// 5. Retornamos el JSON que usará el nodo de Telegram
return { 
  json: { 
    ...r, 
    ok: rpa.resultado === 'PASS', 
    estado: rpa.resultado, 
    pasos_clasificados: pasosClasificados,
    hay_critico: hayCritico,
    tiempos: { accion: tAccion, recuperacion: tRecuperacion, total: tTotal }, 
    mensaje: mensaje 
  } 
};

// ==================================================
// ARMAR RESULTADO DE FALLO
// CRM WINDOWS - T-47
// ==================================================

const r = $('Marcar hora del reinicio1').last().json;
const http = $json;

// Intento actual
const intentoActual =
  Number(r.intento ?? 1);

const maxIntentos =
  Number(r.max ?? 4);

// Tiempos
const ahora = Date.now();

const ref =
  r.t_evento_ms != null
    ? r.t_evento_ms
    : r.t_inicio_ms;

const seg = (a, b) =>
  (a == null || b == null)
    ? null
    : Math.round((b - a) / 100) / 10;

const tiempos = {
  referencia:
    r.t_evento_ms != null
      ? 'evento Zabbix'
      : 'llegada del webhook',

  accion:
    seg(ref, r.t_reinicio_ms),

  recuperacion: null,
  rpa: null,

  total:
    seg(ref, ahora)
};

const hora = ms =>
  ms == null
    ? 'n/d'
    : new Date(ms - 6 * 3600 * 1000)
        .toISOString()
        .replace('T', ' ')
        .slice(0, 19) +
      ' (CR)';

const f = v =>
  v == null
    ? 'n/d'
    : v + ' s';

// Estado HTTP
const estadoHttp =
  http.statusCode !== undefined
    ? http.statusCode
    : 'sin respuesta';

const quedanIntentos =
  intentoActual < maxIntentos;

const verificacion =
  'El CRM Windows continúa sin responder correctamente por HTTP después del intento ' +
  intentoActual +
  ' de ' +
  maxIntentos;

const mensaje = [
  '❌ FALLO: ' +
    r.target +
    ' (' +
    r.incident_type +
    ') sigue sin responder tras la remediación.',

  'Hora del evento: ' +
    (
      r.event_time
        ? r.event_time + ' (Zabbix)'
        : hora(r.t_inicio_ms) + ' (llegada a n8n)'
    ),

  'Hora del fallo: ' +
    hora(ahora),

  'Acción IIS/W3SVC: ' +
    (
      r.reinicio_ok
        ? 'ejecutada'
        : 'con error: ' +
          (
            r.reinicio_error ||
            'desconocido'
          )
    ) +
    ' | HTTP: ' +
    estadoHttp,

  'Verificación: ' +
    verificacion,

  'Intento: ' +
    intentoActual +
    ' de ' +
    maxIntentos,

  quedanIntentos
    ? 'La recuperación automática volverá a intentarse.'
    : 'Se agotaron los 4 intentos automáticos. Se requiere intervención humana. El RPA no se ejecutó.',

  'T-acción: ' +
    f(tiempos.accion) +
    ' | T-total: ' +
    f(tiempos.total)
].join('\n');

return {
  json: {
    ...r,

    estado: 'FALLO',
    ok: false,

    http_status: estadoHttp,
    verificacion,

    intento: intentoActual,
    max: maxIntentos,
    quedan_intentos: quedanIntentos,

    tiempos,
    mensaje
  }
};
